<?php
/** Perplexity: an answer engine with sources, research modes, Spaces, checking sources, the Sonar API. */

return [
    'id' => 'perplexity', 'family' => 'assistants', 'after' => null,
    'title' => L('Perplexity', 'Perplexity'), 'short' => L('Perplexity', 'Perplexity'), 'level' => L('Base', 'Basics'),
    'desc' => L('Cercare con l’AI e le fonti: risposte con citazioni, ricerca approfondita, Spaces, come verificare le fonti e l’API Sonar.', 'Searching with AI and sources: cited answers, deep research, Spaces, how to verify sources and the Sonar API.'),
    'lessons' => [
        lesson('answers', L('Risposte con le fonti', 'Answers with sources'), [
            P('**Perplexity** è un “motore di risposte”: invece di un elenco di link, cerca sul web, legge le pagine e scrive una risposta con le **citazioni numerate** alle fonti. È pensato per domande che richiedono informazioni aggiornate e verificabili.', '**Perplexity** is an “answer engine”: instead of a list of links, it searches the web, reads the pages and writes an answer with **numbered citations** to the sources. It is designed for questions needing up-to-date, verifiable information.'),
            P('Si possono fare **domande di seguito** per approfondire, mantenendo il contesto. Si usa dal web, da app per computer e telefono e dal suo browser. Le domande migliori sono specifiche: “confronta”, “quali sono le differenze”, con luogo e periodo.', 'You can ask **follow-up questions** to dig deeper, keeping the context. It is used from the web, desktop and phone apps and its own browser. The best questions are specific: “compare”, “what are the differences”, with place and time frame.'),
        ], [
            Q('a1', L('Che cosa distingue Perplexity da un motore di ricerca classico?', 'What sets Perplexity apart from a classic search engine?'), [L('Scrive una risposta con citazioni alle fonti', 'It writes an answer with source citations'), L('Mostra solo pubblicità', 'It only shows ads'), L('Non usa internet', 'It does not use the internet'), L('Funziona solo offline', 'It only works offline')], 0, L('Un motore di risposte.', 'An answer engine.')),
            Q('a2', L('A che cosa servono i numeri nelle risposte?', 'What are the numbers in answers for?'), [L('Rimandano alle fonti', 'They point to the sources'), L('Sono voti', 'They are scores'), L('Sono prezzi', 'They are prices'), L('Non significano nulla', 'They mean nothing')], 0, L('Si cliccano per verificare.', 'Click them to verify.')),
            Q('a3', L('Qual è una buona domanda per Perplexity?', 'What is a good question for Perplexity?'), [L('Confronta i bonus edilizi 2026 in Italia per i privati', 'Compare 2026 Italian home-renovation incentives for individuals'), L('Ciao', 'Hi'), L('Dimmi qualcosa', 'Tell me something'), L('Bonus?', 'Bonus?')], 0, L('Specifica, con luogo e periodo.', 'Specific, with place and time.')),
        ], task('text', L('Scrivi una domanda per Perplexity che confronti due cose a tua scelta, indicando **luogo**, **periodo** e chiedendo una **tabella**.', 'Write a Perplexity question comparing two things of your choice, stating **place**, **time frame** and asking for a **table**.'), '', [re('confront|compar|differenz|differen|vs', L('Chiedi un confronto', 'You ask for a comparison')), re('20\d\d|ultim[io]|last|this year|quest’anno|quest\'anno', L('Indichi il periodo', 'You state the period')), re('tabella|table', L('Chiedi una tabella', 'You ask for a table'))], '', 'Confronta in una tabella i costi dell’abbonamento ai trasporti pubblici a Milano e a Torino nel 2026 per gli studenti.'), [
            dMatch(pMatch(), [[L('Citazione', 'Citation'), L('Link alla fonte', 'Link to the source')], [L('Domanda di seguito', 'Follow-up'), L('Approfondisce con contesto', 'Digs deeper with context')], [L('Motore di risposte', 'Answer engine'), L('Risposta scritta, non solo link', 'Written answer, not just links')], [L('Domanda specifica', 'Specific question'), L('Risultati migliori', 'Better results')]], L('Cercare rispondendo.', 'Searching by answering.')),
            dFlash(pFlash(), [[L('Perplexity cita le fonti delle risposte', 'Perplexity cites its answers’ sources'), true], [L('Le fonti non si possono aprire', 'Sources cannot be opened'), false], [L('Si possono fare domande di seguito', 'You can ask follow-ups'), true], [L('Le domande vaghe danno risultati migliori', 'Vague questions give better results'), false]], L('Domande chiare, fonti visibili.', 'Clear questions, visible sources.')),
        ]),
        lesson('research', L('Ricerca approfondita e Spaces', 'Deep research and Spaces'), [
            P('Oltre alla ricerca rapida, Perplexity ha modalità più **approfondite** che fanno molte ricerche di seguito e scrivono un rapporto lungo e strutturato: utili per analisi di mercato, rassegne, preparazione di un viaggio. Si può anche limitare la ricerca a certi tipi di fonti, come articoli accademici.', 'Beyond quick search, Perplexity has more **in-depth** modes that run many searches in a row and write a long, structured report: useful for market analysis, reviews, trip planning. You can also limit the search to certain source types, such as academic papers.'),
            P('Gli **Spaces** raccolgono ricerche su un tema, con istruzioni proprie e file caricati: per esempio uno Space “Tesi di laurea” con le tue note e la richiesta di citare solo fonti accademiche. Le ricerche si possono condividere con un link.', '**Spaces** collect research on a topic, with their own instructions and uploaded files: for example a “Thesis” Space with your notes and a request to cite only academic sources. Research can be shared via a link.'),
        ], [
            Q('r1', L('Quando usare la ricerca approfondita?', 'When should you use deep research?'), [L('Per analisi lunghe che richiedono molte fonti', 'For long analyses needing many sources'), L('Per sapere l’ora', 'To know the time'), L('Per una parola', 'For one word'), L('Mai', 'Never')], 0, L('Richiede più tempo.', 'It takes longer.')),
            Q('r2', L('Che cos’è uno Space?', 'What is a Space?'), [L('Una raccolta di ricerche con istruzioni e file', 'A collection of research with instructions and files'), L('Un abbonamento', 'A subscription'), L('Un browser', 'A browser'), L('Un tipo di fonte', 'A source type')], 0, L('Per progetti su un tema.', 'For topic projects.')),
            Q('r3', L('Si può limitare la ricerca agli articoli accademici?', 'Can you limit search to academic papers?'), [L('Sì', 'Yes'), L('No', 'No'), L('Solo in inglese', 'Only in English'), L('Solo il sabato', 'Only on Saturdays')], 0, L('Utile per lo studio.', 'Useful for study.')),
        ], task('text', L('Scrivi le istruzioni di uno Space per una tesi: righe `Tema:`, `Fonti:` (solo accademiche) e `Formato:` (con citazioni).', 'Write a Space’s instructions for a thesis: lines `Topic:`, `Sources:` (academic only) and `Format:` (with citations).'), "Tema: \nFonti: \nFormato: ", [re('^(Tema|Topic):\s*\S.{5,}', L('Il tema', 'The topic')), re('^(Fonti|Sources):.*(accademic|academic|scientific|scientific)', L('Fonti accademiche', 'Academic sources')), re('^(Formato|Format):.*(citazion|citation|cita|cite)', L('Con citazioni', 'With citations'))], '', "Tema: impatto del lavoro da remoto sulla produttività in Europa.\nFonti: solo articoli accademici e rapporti di istituti di ricerca.\nFormato: punti brevi con citazione numerata per ogni affermazione."), [
            dOrder(pSort(), [L('Crea uno Space con istruzioni', 'Create a Space with instructions'), L('Carica le tue note', 'Upload your notes'), L('Avvia una ricerca approfondita', 'Start a deep research'), L('Verifica le fonti citate', 'Verify the cited sources'), L('Condividi il rapporto', 'Share the report')], L('Un progetto di ricerca.', 'A research project.')),
            dFlash(pFlash(), [[L('La ricerca approfondita produce rapporti strutturati', 'Deep research produces structured reports'), true], [L('Uno Space non accetta file', 'A Space accepts no files'), false], [L('Le ricerche si possono condividere', 'Research can be shared'), true], [L('La ricerca approfondita è istantanea', 'Deep research is instant'), false]], L('Ricercare con metodo.', 'Researching with method.')),
        ]),
        lesson('verify', L('Verificare le fonti', 'Verifying sources'), [
            P('Le citazioni rendono le risposte **verificabili**, non automaticamente vere: il modello può riassumere male una pagina, o citare una fonte poco affidabile. Apri le fonti per le affermazioni importanti e controlla che dicano davvero quello che la risposta afferma.', 'Citations make answers **verifiable**, not automatically true: the model can misread a page, or cite an unreliable source. Open the sources for important claims and check they really say what the answer states.'),
            P('Valuta le fonti: chi le ha scritte (ente pubblico, giornale, blog anonimo)? Quando? Sono originali o copiano altri siti? Per numeri e leggi preferisci le **fonti primarie** (gazzetta ufficiale, siti istituzionali, studi originali).', 'Assess sources: who wrote them (public body, newspaper, anonymous blog)? When? Are they original or copying other sites? For figures and laws prefer **primary sources** (official gazette, institutional sites, original studies).'),
        ], [
            Q('v1', L('Una risposta con citazioni è sicuramente vera?', 'Is an answer with citations surely true?'), [L('No, è verificabile ma va controllata', 'No, it is verifiable but must be checked'), L('Sì, sempre', 'Yes, always'), L('Solo se lunga', 'Only if long'), L('Solo in inglese', 'Only in English')], 0, L('La fonte può dire altro.', 'The source may say otherwise.')),
            Q('v2', L('Quali fonti preferire per una legge?', 'Which sources to prefer for a law?'), [L('Fonti primarie, come la gazzetta ufficiale', 'Primary sources, like the official gazette'), L('Un blog anonimo', 'An anonymous blog'), L('Un commento social', 'A social comment'), L('Nessuna', 'None')], 0, L('Il testo originale.', 'The original text.')),
            Q('v3', L('Che cosa chiederti su una fonte?', 'What should you ask about a source?'), [L('Chi l’ha scritta e quando', 'Who wrote it and when'), L('Di che colore è il sito', 'The site’s colour'), L('Quanto è lunga', 'How long it is'), L('Niente', 'Nothing')], 0, L('Autore e data.', 'Author and date.')),
        ], task('text', L('Scrivi una checklist di tre controlli da fare su una fonte citata, una riga per controllo con `[ ]`.', 'Write a checklist of three checks for a cited source, one line per check with `[ ]`.'), "[ ] \n[ ] \n[ ] ", [re('^\[ \]\s*\S.*\n\[ \]\s*\S.*\n\[ \]\s*\S', L('Tre controlli', 'Three checks')), re('autor|chi |who|author|ente', L('Chi l’ha scritta', 'Who wrote it')), re('data|quando|when|date|aggiorn|updated', L('Quando', 'When'))], '', "[ ] chi è l’autore o l’ente che la pubblica\n[ ] la data di pubblicazione o aggiornamento\n[ ] se dice davvero quello che riporta la risposta"), [
            dMatch(pMatch(), [[L('Fonte primaria', 'Primary source'), L('Il documento originale', 'The original document')], [L('Autore', 'Author'), L('Chi l’ha scritta', 'Who wrote it')], [L('Data', 'Date'), L('Quanto è aggiornata', 'How current it is')], [L('Verifica', 'Verification'), L('Aprire e leggere la fonte', 'Opening and reading the source')]], L('Valutare le fonti.', 'Assessing sources.')),
            dFlash(pFlash(), [[L('Il modello può riassumere male una fonte', 'The model can misread a source'), true], [L('Un blog anonimo vale quanto un sito istituzionale', 'An anonymous blog equals an institutional site'), false], [L('Per i numeri conviene la fonte originale', 'For figures the original source is best'), true], [L('Le citazioni garantiscono la verità', 'Citations guarantee truth'), false]], L('Verificabile non vuol dire vero.', 'Verifiable does not mean true.')),
        ]),
        lesson('api', L('L’API Sonar', 'The Sonar API'), [
            P('Perplexity offre un’API con i modelli **Sonar**, che cercano sul web e restituiscono risposte con le fonti: utile per aggiungere ricerca aggiornata alle tue app. L’API è **compatibile con quella di OpenAI**: si usa il suo SDK cambiando `base_url`.', 'Perplexity offers an API with **Sonar** models, which search the web and return answers with sources: useful to add up-to-date search to your apps. The API is **OpenAI-compatible**: you use its SDK changing `base_url`.'),
            C('import os
from openai import OpenAI

client = OpenAI(api_key=os.environ["PERPLEXITY_API_KEY"], base_url="https://api.perplexity.ai")
r = client.chat.completions.create(
    model="sonar",
    messages=[{"role": "user", "content": "Quali sono le ultime novità sull’AI Act?"}],
)
print(r.choices[0].message.content)', 'python'),
            P('Le risposte includono l’elenco delle fonti usate. Come sempre: chiave in una variabile d’ambiente, costi a consumo, e controlla nella documentazione i modelli disponibili.', 'Responses include the list of sources used. As always: key in an environment variable, pay-as-you-go costs, and check the documentation for available models.'),
        ], [
            Q('s1', L('Come si chiamano i modelli dell’API di Perplexity?', 'What are Perplexity’s API models called?'), ['Sonar', 'Sonata', 'Echo', 'Radar'], 0, L('Cercano sul web.', 'They search the web.')),
            Q('s2', L('Quale SDK si può usare?', 'Which SDK can be used?'), [L('Quello di OpenAI, cambiando base_url', 'OpenAI’s, changing base_url'), L('Nessuno', 'None'), L('Solo uno segreto', 'Only a secret one'), L('Quello di Excel', 'Excel’s')], 0, L('API compatibile.', 'Compatible API.')),
            Q('s3', L('Che cosa aggiunge Sonar alle tue app?', 'What does Sonar add to your apps?'), [L('Risposte aggiornate con fonti dal web', 'Up-to-date answers with web sources'), L('Immagini', 'Images'), L('Database', 'Databases'), L('Pagamenti', 'Payments')], 0, L('Ricerca integrata.', 'Built-in search.')),
        ], task('python', L('Crea il client `OpenAI` puntato a `https://api.perplexity.ai` con la chiave da `os.environ["PERPLEXITY_API_KEY"]` e chiama `chat.completions.create` con `model="sonar"`.', 'Create the `OpenAI` client pointed at `https://api.perplexity.ai` with the key from `os.environ["PERPLEXITY_API_KEY"]` and call `chat.completions.create` with `model="sonar"`.'), "import os\nfrom openai import OpenAI\n", [re('OpenAI\s*\(\s*api_key\s*=\s*os\.environ\s*\[\s*["\']PERPLEXITY_API_KEY["\']\s*\]\s*,\s*base_url\s*=\s*["\']https://api\.perplexity\.ai["\']\s*\)', L('Il client', 'The client')), re('chat\.completions\.create\s*\([\s\S]*model\s*=\s*["\']sonar["\']', L('Il modello Sonar', 'The Sonar model'))], '', "client = OpenAI(api_key=os.environ[\"PERPLEXITY_API_KEY\"], base_url=\"https://api.perplexity.ai\")\nr = client.chat.completions.create(model=\"sonar\", messages=[{\"role\": \"user\", \"content\": \"Novità sull’AI Act?\"}])"), [
            dBlanks(pFill(), "client = OpenAI(api_key=chiave, ___=\"https://api.perplexity.ai\")\nr = client.chat.completions.create(model=\"___\", messages=msgs)", ['base_url', 'sonar'], ['url', 'gpt', 'host'], L('Puntare il client a Perplexity.', 'Pointing the client at Perplexity.')),
            dMatch(pMatch(), [['Sonar', L('Modelli con ricerca web', 'Models with web search')], ['base_url', L('Indirizzo dell’API', 'API address')], ['PERPLEXITY_API_KEY', L('Chiave nell’ambiente', 'Key in the environment')], [L('Fonti', 'Sources'), L('Restituite con la risposta', 'Returned with the answer')]], L('Ricerca nelle tue app.', 'Search in your apps.')),
        ]),
        lesson('workflow', L('Un metodo di ricerca', 'A research method'), [
            P('Una buona ricerca con Perplexity procede per passi: una **domanda precisa**, la lettura delle **fonti citate**, poi **domande di approfondimento** nella stessa conversazione. Puoi chiedere di confrontare fonti diverse o di limitarsi a fonti accademiche o ufficiali.', 'Good research with Perplexity goes step by step: a **precise question**, reading the **cited sources**, then **follow-up questions** in the same thread. You can ask it to compare different sources or to stick to academic or official ones.'),
            P('Alla fine, scrivi tu la sintesi: annota quali affermazioni vengono da quale fonte, e dove le fonti **non sono d’accordo**. Una risposta senza fonti solide va trattata come un’ipotesi.', 'At the end, write the synthesis yourself: note which claims come from which source, and where the sources **disagree**. An answer without solid sources should be treated as a hypothesis.'),
        ], [
            Q('wf1', L('Qual è il primo passo di una buona ricerca?', 'What is the first step of good research?'), [L('Una domanda precisa', 'A precise question'), L('Copiare la prima risposta', 'Copying the first answer'), L('Aprire dieci schede a caso', 'Opening ten tabs at random'), L('Chiedere un riassunto vuoto', 'Asking for an empty summary')], 0, L('Domanda vaga, risposta vaga.', 'Vague question, vague answer.')),
            Q('wf2', L('Che cosa fai quando le fonti non sono d’accordo?', 'What do you do when sources disagree?'), [L('Lo annoti e approfondisci', 'You note it and dig deeper'), L('Scegli la più corta', 'You pick the shortest'), L('Ignori la differenza', 'You ignore the difference'), L('Chiudi la ricerca', 'You stop researching')], 0, L('Il disaccordo è un’informazione.', 'Disagreement is information.')),
            Q('wf3', L('Come tratti un’affermazione senza fonti solide?', 'How do you treat a claim without solid sources?'), [L('Come un’ipotesi da verificare', 'As a hypothesis to check'), L('Come un fatto', 'As a fact'), L('Come una citazione', 'As a quote'), L('La pubblichi', 'You publish it')], 0, L('Prima si verifica.', 'Check first.')),
        ], task('text', L('Scrivi una domanda precisa che inizia con `Domanda:` e una richiesta di approfondimento che inizia con `Approfondisci:`.', 'Write a precise question starting with `Domanda:` and a follow-up starting with `Approfondisci:`.'), '', [re('^Domanda\s*:\s*\S.{10,}\?', L('Una domanda precisa', 'A precise question')), re('^Approfondisci\s*:\s*\S.{5,}', L('Un approfondimento', 'A follow-up'))], '', "Domanda: quali sono gli effetti dello smart working sulla produttività secondo studi dal 2020?\nApprofondisci: confronta i risultati degli studi europei con quelli americani."), [
            dOrder(pSort(), [L('Domanda precisa', 'Precise question'), L('Lettura delle fonti', 'Reading sources'), L('Domande di approfondimento', 'Follow-up questions'), L('Sintesi scritta da te', 'Your own synthesis')], L('Un metodo di ricerca.', 'A research method.')),
            dFlash(pFlash(), [[L('Si possono chiedere solo fonti ufficiali', 'You can ask for official sources only'), true], [L('Le fonti citate non vanno mai aperte', 'Cited sources should never be opened'), false], [L('Il disaccordo tra fonti va annotato', 'Disagreement between sources should be noted'), true], [L('Una risposta senza fonti è un fatto certo', 'An answer without sources is a certain fact'), false]], L('Ricercare con metodo.', 'Researching with method.')),
        ]),
    ],
];
